	title 'Desk Manager  GS ROM 3.0'************************************************************************ Desk Manager  * for the Apple II GS** original CDA code by John Worthinton.* original NDA code by Steven Glass** Additions and alterations by Steven Glass and* Konstantin Othmer** System 6.0 work by Dave Lyons**********************************************************************************************************************************************			         **	Copyright (C) 1985-1991	         **	All Rights Reserved		         **	Apple Computer, Inc.	         **			         *********************************************************************************************************************************************** Change History** Version 1.0*    John Worthington 20 May 86** Version 2.0*    Steven Glass	  Winter 86-87** Version 3.0*    Steven Glass	  Fall 87** Change History** 08 Oct 87    Steven Glass** RAM patches included into rom source for first time.  Source* code was re-organized.** 12 Oct 87    Steven Glass** The orig ROM and ROM 2 code was built	with MSB on.  The* Desk Mgr patch was built with MSB off.  We adjust MSB* below depending on what code is being	assembled.*** 23 Mar 88	Steven Glass** There was a space in definition equs for GetNumDas.  This* caused wrong offsets on stack to be used.** 31 Mar 88	Steven Glass** SystemEvent now looks at the state of CDAs before sending* events on to NDAs.  This prevents CDAs from being locked out* when an NDA window is active.** 16 Jun 88 	Steven Glass		*			* OpenNDA call looks for zero coming back from NDA.** 19 Jul 88	Steven Glass** The DAHandler has been separated from the BootInit code.  It* has been re-organized and uses much less code.  Finally, a bug* where the dbr was being pulled after the processor reg (p) was* pushed is fixed.	*** 25 Jul 88	Steven Glass** Error code from InstCDA was in wrong reg.*** Sept-Oct 88	Konstantin Othmer** Scrolling was added to CDA menu so more than 13 CDAs could be installed.* A run queue was added so anyone can get a call at system task time.* Removal of CDAs and NDAs added.** 25 Oct 88	Steven Glass** Major re-organization of files.  The purpose of the new orgainization* is to allow the patch file to share code and objecs with the ROM.** The new orgainzation keeps the init calls in Desk.asm and* moves all other code into one of three files:**      CDACalls.asm*      CDAMenu.asm*      NDACalls.asm** The patch file for ROM 2.0 uses all of NDAcalls, all of CDAMenu* and small parts of CDACalls and Desk.** A fifth file Desk.Equates.asm is also used.  It contains the * global equates that are shared by all.** 02 Jun 89	Steven Glass** Zeroed variable in NDA init code.** 15 Feb 90	Harry Yee* Fix bug in RemoveNDA. The NDA was not being removed from * NDA list properly. Bumped version number from 3.0 to 3.1** 26-Sep-90	Dave Lyons** Changed macro names so it'll build.  setmode8 --> shortmx,* setmode16 --> longmx.** 19-Feb-91	Dave Lyons** Adding call table entries for 6.0 calls, even though this* call table doesn't actually get used for TS2 and TS3.** 4-Mar-91	Dave Lyons** Added SendRequest calls at the end of DeskStartUp and* DeskShutDown (used by TS2).** 5-Aug-91	Dave Lyons** Made DeskStartUp paranoid about the environment.  Checks* for GS/OS and for several tools being started; if things* aren't right, DeskStartUp returns, taking no action.** 16-Sep-91	Dave Lyons** Made DeskStartUp and DeskShutDown maintain RealDeskStatus,* for use by FixAppleMenu.** 17-Sep-91	Dave Lyons** Small changed to support moving calls into Tool.Setup.** 8-Dec-91	Dave Lyons** Conditioned out DeskShutDown fiddling with special bits* in $E100BE, since this is part of the ROM 3 kludge to make* System 4.0 run.  No point in having it lying around RAM,* and it makes old versions of SoftSwitch not run on ROM 1* (the versions that don't run on ROM 3, since they check* for $E100BE to be zero instead of checking bit 15 = GS/OS* busy).**********************************************************	eject	include 'all.macros'	include '::sys.equs.asm'	include 'e16.memory';=================================================;; Special Macros;	MACRO&lab	movelong &src,&dest&lab	lda &src	sta &dest	lda &src+2	sta &dest+2	mendDAVersionNumber	equ $0301	include 'Desk.Equates.asm'	title 'Desk Manager--CALL TABLE'****************************************************************** DACallTable** *****************************************************************	EXPORT DACallTableDACallTable	PROCTheBeginning	DC.L (TheEnd-TheBeginning)/4 ; num calls + 1	DC.L DABootInit-1	; 1	DC.L DAStartup-1	; 2	DC.L DAShutdown-1	; 3	DC.L DAVersion-1	; 4	DC.L DAReset-1	; 5	DC.L DAStatus-1	; 6	DC.L oEndCall0-1	; 7     reserved	DC.L oEndCall0-1	; 8     reserved	DC.L SaveScreen-1	; 9	DC.L RestScreen-1	; A	EXPORT SaveAllTableEntrySaveAllTableEntry		;       	DC.L SaveAll-1	; B	DC.L RestAll-1	; C	DC.L oEndCall0-1	; D	DC.L InstallNDA-1	; E	DC.L instcda-1	; F	DC.L oEndCall0-1	; 10	DC.L choosecda-1	; 11	DC.L oEndCall0-1	; 12	DC.L setdastrptr-1	; 13	DC.L getdastrptr-1	; 14	DC.L OpenNDA-1	; 15	DC.L CloseNDA-1	; 16	DC.L SystemClick-1	; 17	DC.L SystemEdit-1	; 18	DC.L SystemTask-1	; 19	DC.L SystemEvent-1	; 1A	DC.L GetNumNDAs-1	; 1B	DC.L CloseNDAbyWinPtr-1 ; 1C	DC.L CloseAllNDAs-1	; 1D	DC.L FixAppleMenu2-1 ; 1E	DC.L AddToRunQ-1	; 1F	DC.L RemoveFromRunQ-1 ;20	DC.L RemoveCDA-1	;21	DC.L RemoveNDA-1	;22	dc.l GetIndDAInfo	;2305 added 19-Feb-91 DAL	dc.l CallDeskAcc	;2405 added 19-Feb-91 DAL	dc.l GetDeskGlobal	;2505 added 19-Feb-91 DALTheEnd	ENDP*****************************************************************DABootInit	PROC** This is the routine that inits the desk manager* at tool startup time.  This routine is only called* by the Tool Locator.**** Inputs:*	none** Outputs:*	none** External Refs:	import DAHandler** Entry Points:*	none*	longa on	; mode	longi on** Change History** Original Version	John Worthington** Second ROM	John Worthington**   ROM DAs are re-installed if desired*  ** Third ROM	Steven Glass**   Support for NDA's (originally in RAM) added.*** 3 Oct 88	Konstantin Othmer**  Added initialization for run queue at system task time.*****************************************************************	jsr DoCDAInit	jsr DoNDAInit	jsr SetPanelActive	jml oEndCall0	ENDP*****************************************************************DoNDAInit	PROC EXPORT** This routine contains the code that inits the NDA system.* It used to be part of the BootInit call but I've separated* it to make it more useable with the ROM patch for version* 2.0 of the ROM>*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 02 Jun 89	Steven Glass** Zeroed the EntryCounter*****************************************************************    IF RAMVersion=0 THEN;-----------------------------------------------------------;; Init this counter.;	lda #0	sta >EntryCount;-------------------------------------------------;; Init stuff for NDAs.  Note that NDAListHandle; on direct page is	not valid yet.;	jsr StartNDACall	; get some direct page spack off stack;-------------------------------------------------;; Get handle for desk manager globals and put ; result on direct page.;	lda #SizeOfDeskGlobals	ldx #attrNoSpec	jsr DAGetMem	bcc @1	brl DieHorribly@1	sta NDAListHandle	stx NDAListHandle+2;-------------------------------------------------;; Also put copy of handle in WAP for desk mgr;	PushWord #$0000	; system	PushWord #5	; tool 5	pei NDAListHandle+2	; handle to globals	pei NDAListHandle	_SetWAP;-------------------------------------------------;; Deref and lock handle so can init some of the; fields in memory.;	jsr DerefNDAList	lda #0	; clear the a-reg	ldy #o_NumEntries	; no ndas are installed yet	sta [NDAListPtr],y	ldy #o_ActiveFlag	; DeskStartup has not been called	sta [NDAListPtr],y	ldy #o_NotAgain	; CDA menu is not active.	sta [NDAListPtr],y	ldy #o_TaskQueueHeader ;beginning of run queue link list	sta [NDAListPtr],y	; make it a null pointer	iny	iny	sta [NDAListPtr],y	pha	; get address of tick count.	pha	PushWord #5	_GetAddr	ldy #o_TickAddress	pla	sta [NDAListPtr],y	iny	iny	pla	sta [NDAListPtr],y;-------------------------------------------------;; Unlock the handle	and give back the direct; page.;	jsr UnlockNDAList	jsr EndNDACall    ELSE	phd	lda #0	tcd	pushlong #pg2kludge	; a kludge to install foreign kludges	pushlong #dastr	_SetDAStrPtr	pld    ENDIF	RTS	ENDP*****************************************************************DoCDAInit	PROC EXPORT** This routine contains the code that inits the CDA system.* It used to be part of the BootInit call but I've separated* it to make it more useable with the ROM patch for version* 2.0 of the ROM.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************;-------------------------------------------------;; Start setting up CDA stuff.  (Do this	setup ; with interrupts off.);	php	; save processor	sei	; turn interrupts off	PushWord #$12	; install the address of the cda int	PushLong #daHandler	; handler.	_setvector	lda #$FF	; init the NumInts global.	sta >numints	; note that this trashes the next byte too!!!!!!!; The kbm data interrupt is now initialzed by Fern...	lda #monkeyin	; init the KeyInput	global.	sta >keyinput    IF RAMVersion=0 THEN	lda #$00	; init the NumDAs global	sta >numdas	lda #$08	; init the RoomLeft	global	sta >roomleft	pha	; get id for the CDATabHndl	pushword #$5000	; it will have a type of $5	_getnewid	pla	sta >idnum	lda #$0020	; Get memory for CDATabHndl 	ldx #attrNoSpec	; (only $20 bytes)	jsr DAGetMem	bcc GotIt	brl DieHorriblyGotIt	sta >cdatabhndl	txa	sta >cdatabhndl+2	pushlong #pg2kludge	; install pg2kludge	as a user accessory	_InstallCDA	pushlong #pg2kludge	; a kludge to install foreign kludges	pushlong #dastr	_SetDAStrPtr	jsl $FFC06E	; install the rom-based da's    ENDIF	plp	; restore interrupt	state.	rts	ENDP*****************************************************************DAGetMem	PROC EXPORT** Routine to get memory with the desk manager's* user id.  (This used to be part of the boot init code.* It is now separate to make building the patch easier.)** Inputs:*    a-reg  Size*    x-reg  Attributes** Outputs:**    a-reg  low word of handle or error	code*    x-reg  high word of handle*    carry  clear if no error, set if error.*** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	pha	; space for result handle	pha	PushWord #0	; high word of size	pha	; low word of size	PushWord >IDNum	phx	; attributes	pha	; loc info (not used)	pha	_NewHandle	bcs GetMemOops	pla	plx	rtsGetMemOops	plx	plx	rts	ENDP*********************************************************** DAStartup** This call activates NDA features for applications* that want them.** Change History** 09 Oct 87    Steven Glass**    Original ROM and ROM 2 did not do anything*    with this call	and it was always patched.***********************************************************	EXPORT DAStartupDAStartup	PROC*** added 5-Aug-91 DAL -- if proper environment is not set up, do nothing	pha	phy	lda >$e100bc	;OS_Kind	and #$00ff	dec a	bne @error	;must be $01=GS/OS	ldx #@neededToolsEnd-@neededTools@checkOneTool	dex	bmi @toolsAreHere	phx	lda >@neededTools,x	and #$00FF	ora #$0600	;compute xxxStatus function code	tax	pea 0	jsl $e10000	;make the call	pla	plx	tay	bne @checkOneTool	;nonzero status --> go back for more@error	ply	pla	bra @outtaHere@neededTools	dc.b $0E	;window	dc.b $0F	;menu	dc.b $10	;control	dc.b $14	;line edit	dc.b $15	;dialog;;;	dc.b $16	;scrap (omitted...I'm feeling generous)@neededToolsEnd@toolsAreHere	ply	pla*** end 5-Aug-91 DAL	jsr StartNDACall	jsr DerefNDAList	ldy #o_ActiveFlag	lda #$8000	sta [NDAListPtr],y	lda #$ffff	;16-Sep-91 DAL	sta >RealDeskStatus	;16-Sep-91 DAL	jsr InitAll	; wake everyone up (a-reg is input here)	jsr UnlockNDAList	jsr EndNDACall*** added 4-Mar-91 DAL	pea $0502	;request code	lda #0	pha	;how = everybody	pha	pha	;target = nil	pha	pha	;dataIn = nil	pha	pha	;dataOut = nil	_SendRequest@outtaHere	jml oEndCall0	ENDP*********************************************************** DAShutdown** This call deactivates NDA features for applications* that want them.  In addition, it causes all installed* DA's (New and Classic) to get a shutdown call.** Change History** 09 Oct 87    Steven Glass**    Original ROM and ROM 2 did not do anything*    with this call	and it was always patched.** XX Oct 88	Steven Glass** Horrible hack added.** 07 Dec 88	Steven Glass** Added setting of PatchLoadedBit.*********************************************************DAShutdown	PROC EXPORT*** This "Kidding" stuff isn't needed in RAM!  8-Dec-91 DAL;;; (I should put a cool conditional-assembly symbol in the;;; patch makefiles in case somebody does a new ROM, but that;;; seems unlikely, so I'll be lazy.)	if 0 then;-----------------------------------------------------------;; This is part of our horrible hack to keep GS/OS from; system disk 4.0 running under the 3.0 rom.;; If P8 is active now, we must clear the bit that; tells YouveGotToBeKidding not to patch the os.;; Also always set the patch loaded bit so that ; the tool locator can know when the patch has; finished loading;	pha	; save the a-reg	lda >OS_Flag	; set the patch loaded bit: there is no way we can	ora #PatchLoadedBit	; get here without loading the patch first.	sta >OS_Flag	lda >OS_Kind	; is P8 active now	and #$00FF	bne NeverMind	; no, so skip the rest	lda >OS_Flag	; look at the OS_flag. If bit 1 is set	and #BadOSBit	; then this is a situation that we do our silly stuff	beq NeverMind	; If not, we skip the rest	lda >OS_Flag	; Clear bit 0 so that the patch routine will try again.	and #$FFFF-SpecialBit	sta >OS_FlagNeverMind	pla	; restore the a-reg	endif*** end 8-Dec-91;-----------------------------------------------------------;-------------------------------------------------;; First shutdown all the NDAs and clear	the; active flag in the global data structure.;	phy	; save WAP value on	stack	pha	_CloseAllNDAs	; close all open NDAs	pla	ply	jsr StartNDACall	jsr DerefNDAList	ldy #o_ActiveFlag	lda #$0000	sta [NDAListPtr],y	sta >RealDeskStatus	;16-Sep-91 DAL	jsr InitAll	; shut all NDAs down (a-reg is intput here)	jsr UnlockNDAList;-----------------------------------------------------;; Now comes the hard work of sending the shutdown; message to the classic desk accessories.;;; Look at the count	of das.; Strange Notes:;;    This number is	not what it seems.	The control panel;    is not counted	in this value nor is the handle to the;    control panel in the list.;;    If the value is 1, the only CDA installed is the Alt;    display mode.;;    So the number here is the number of CDAs other than the;    control panel that have been installed. 	lda >numdas	; Get the number and dec by one	dec a	;	bmi SkipThis	; If neg, something	weird has;		; happened and we quit;		; (its Weird cause Alt disp mode;		; is supposed to be	there.)	pha	; put this on stack	as counter	lda >cdatabhndl	; get the handle to	the list	sta NDAListHandle	lda >cdatabhndl+2	sta NDAListHandle+2	jsr DerefNDAList	lda NDAListPtr	sta PtrToThisOne	lda NDAListPtr+2	sta PtrToThisOne+2Loop		; ; shut them down one at a time.	lda [PtrToThisOne]	; get the handle to	the CDA out of table	sta NDAHandle	ldy #2	lda [PtrToThisOne],y	sta NDAHandle+2	jsr DerefNDAHandle	lda NDAPtr+1	; look at the address of the da	cmp #$F000	; is it in ROM?	bcs SkipThisCall	; don't make call to rom DA's	jsl CallCDA	; call this thingSkipThisCall		; 	lda PtrToThisOne	clc	adc #4	sta PtrToThisOne	bcc NoBump2	inc PtrToThisOne+2NoBump2		 	lda 1,s	; dec the counter	dec a	sta 1,s	bpl Loop	; if still positive, there is more	pla	; pull counter off stack	jsr UnlockNDAList	; unlock the CDA listSkipThis	jsr EndNDACall*** added 4-Mar-91 DAL	pea $0503	;request code for DeskShutDown	lda #0	pha	;how = everybody	pha	pha	;target = nil	pha	pha	;dataIn = nil	pha	pha	;dataOut = nil	_SendRequest	jml oEndCall0;;;	export RealDeskStatus;;;RealDeskStatus	dc.w 0;-----------------------------------------------------;; local routine to actually call the CDA;CallCDA		; 	lda [NDAPtr]	; get length byte	and #$00FF	; mask off first char	clc	; add 1 for length byte and 4	adc #6	; for main entry point to find;		; and 1 for high 2 bytes	tay	; shutdown entry point	lda [NDAPtr],y	pha	dey	lda [NDAPtr],y	phb	dec a	sta 1,s	rtl	ENDP****************************************************************** InitAll** This routine sends the word passed in	the a register to* each of the NDAs in the list.*****************************************************************	EXPORT InitAllInitAll	PROC	DefineStackCounter	wordMsgToSend	word	pha	; put msg to send on stack	PushWord #0	; init counter on stack	lda NDAListPtr	clc	adc #SizeofDeskGlobals	sta PtrToThisOne	lda NDAListPtr+2	bcc NoCarry	inc aNoCarry	sta PtrToThisOne+2InitLoop		; ; keep initing until done	lda Counter,s	cmp [NDAListPtr]	bcs AllDone; Stack Equates are off by 2 after this call.	jsr SetResID	lda MsgToSend+2,s	jsl SendInit	jsr RepResID; Stack equates are now correct.	lda Counter,s	; bump the counter	inc a	sta Counter,s	lda PtrToThisOne	; bump the PtrToThisOne	clc	adc #NDARecSize	sta PtrToThisOne	bcc NoCarry2	inc PtrToThisOne+2NoCarry2	bra InitLoop	; do it againAllDone		; 	pla	; clear the stack	pla	rts	ENDP*******************************************************************************************************************	EXPORT DAVersionDAVersion	PROCret1	equ 1ret2	equ ret1+3result	equ ret2+3	lda #DAVersionNumber	sta result,s	jml oEndCall0	ENDP*******************************************************************************************************************	EXPORT DAResetDAReset	PROC	shortmx	lda #$FF	sta >numints	longmx	jml oEndCall0	ENDP*********************************************************** DAStatus** This routine returns whether or not the DestStartup* call has been made.  ** Change History** 09 Oct 87        Steven Glass**    Original ROM and ROM 2 always returned true but *    were also always patched out.************************************************************	EXPORT DAStatusDAStatus	PROCResult	equ FirstInput	jsr StartNDACall	jsr DerefNDAList	ldy #o_ActiveFlag	lda [NDAListPtr],y	sta Result	jsr UnlockNDAList	jsr EndNDACall	jml oEndCall0	ENDP	END